pair A, B, C, D, O;

A = (3,4);
C = (7,10);
O = (A + C)/2;
B = O + abs(O - A)*dir(170);
D = O + abs(O - A)*dir(350);

draw(Circle(O,abs(O - A)));
draw(A--C);
